    pontos:[ { ico:'📊', t:'Mediana', d:'custos unitários menores ou iguais à mediana do item' }, { ico:'🏛️', t:'PNCP', d:'painel para consulta de preços do Portal' }, { ico:'➕', t:'Parâmetros', d:'adotados de forma combinada ou não' } ],
