    pontos:[ { ico:'🛒', t:'Qualidade comum', d:'não superior à necessária à finalidade' }, { ico:'💎', t:'Luxo vedado', d:'o art. 20 não traz exceção para recepções' }, { ico:'📜', t:'Regulamento', d:'cada Poder define os limites comum e luxo' } ],
