    regra:'Adota-se o {0|pregão} sempre que o objeto possuir {1|padrões de desempenho e qualidade} objetivamente definidos pelo edital, por meio de {2|especificações usuais de mercado}; não se aplica a serviços técnicos de natureza {3|predominantemente intelectual}.',
    pontos:[ { ico:'🛒', t:'Pregão', d:'modalidade adotada para objetos padronizáveis' }, { ico:'📏', t:'Padrões objetivos', d:'desempenho e qualidade definidos no edital' }, { ico:'🏪', t:'Usuais de mercado', d:'especificações comuns, sem solução inovadora' }, { ico:'🧠', t:'Serviço intelectual', d:'serviço técnico intelectual fica fora do pregão' } ],
