    pontos:[ { ico:'⚖️', t:'Equidade', d:'terceiro critério, conforme regulamento' }, { ico:'📍', t:'Preferência local', d:'empresas do território do Estado ou do DF' }, { ico:'🇧🇷', t:'Empresas brasileiras', d:'segunda preferência, em igualdade de condições' } ],
