    regra:'Pode-se exigir {0|registro ou inscrição na entidade profissional} competente e atestados com quantidades mínimas de até {1|50%} das parcelas de maior relevância, {2|vedadas limitações de tempo e de locais específicos}.',
    pontos:[ { ico:'🪪', t:'Registro profissional', d:'na entidade competente, quando for o caso' }, { ico:'5️⃣', t:'Até 50%', d:'quantidade mínima das parcelas relevantes' }, { ico:'🚫', t:'Sem tempo e local', d:'são vedadas limitações relativas aos atestados' } ],
